/**
 * Rebuild GitHub API + thread handles for inbound hooks and stream events.
 */
import { callGitHubApi, createGitHubCommitStatus, createGitHubIssueComment, createGitHubOctokit, githubEnterpriseCloudApiBaseUrl, createGitHubReaction, createGitHubReviewCommentReply, } from "./api.js";
import { createGitHubCheck } from "./checks.js";
/** Hidden marker on outbound GitHub comments so inbound dispatch ignores them. */
export const GITHUB_OUTBOUND_MARKER = "<!-- agent-serve-github -->";
export function formatGitHubOutboundComment(body) {
    if (body.includes(GITHUB_OUTBOUND_MARKER)) {
        return body;
    }
    return `${body.trimEnd()}\n\n${GITHUB_OUTBOUND_MARKER}`;
}
export function buildGitHubBinding(input) {
    const { config, state } = input;
    const repository = {
        fullName: `${state.owner}/${state.repo}`,
        url: state.repositoryUrl ?? `https://github.com/${state.owner}/${state.repo}`,
        owner: state.owner,
        name: state.repo,
        ...(state.repositoryId === null ? {} : { id: state.repositoryId }),
    };
    const installationId = state.installationId ?? undefined;
    const octokitPromises = new Map();
    const getOctokit = (request) => {
        const enterprise = githubEnterpriseCloudApiBaseUrl(request?.host);
        const key = enterprise ?? "";
        let pending = octokitPromises.get(key);
        if (pending === undefined) {
            pending = createGitHubOctokit({
                api: config.api,
                credentials: config.credentials,
                installationId,
                host: enterprise === undefined ? undefined : request?.host,
            });
            octokitPromises.set(key, pending);
        }
        return pending;
    };
    const github = {
        installationId,
        repository,
        getOctokit,
        request(req) {
            return callGitHubApi({
                api: config.api,
                body: req.body,
                credentials: config.credentials,
                installationId,
                method: req.method,
                path: req.path,
            });
        },
        createStatus(status) {
            return createGitHubCommitStatus({
                api: config.api,
                credentials: config.credentials,
                installationId,
                owner: state.owner,
                repo: state.repo,
                sha: status.sha,
                state: status.state,
                ...(status.context === undefined ? {} : { context: status.context }),
                ...(status.description === undefined ? {} : { description: status.description }),
                ...(status.targetUrl === undefined ? {} : { targetUrl: status.targetUrl }),
            });
        },
        createCheck(check) {
            return createGitHubCheck({
                ...check,
                github: { getOctokit },
                owner: state.owner,
                repo: state.repo,
            });
        },
    };
    const thread = {
        kind: state.conversationKind,
        post(message) {
            if (state.conversationKind === "review_thread") {
                return createGitHubReviewCommentReply({
                    api: config.api,
                    body: message,
                    commentId: requiredNumber(state.reviewThreadRootCommentId ?? state.reviewCommentId, "reviewThreadRootCommentId"),
                    credentials: config.credentials,
                    installationId,
                    owner: state.owner,
                    pullRequestNumber: requiredNumber(state.pullRequestNumber, "pullRequestNumber"),
                    repo: state.repo,
                });
            }
            return createGitHubIssueComment({
                api: config.api,
                body: message,
                credentials: config.credentials,
                installationId,
                issueNumber: requiredNumber(state.issueNumber ?? state.pullRequestNumber, "issueNumber"),
                owner: state.owner,
                repo: state.repo,
            });
        },
        async react(content) {
            const commentId = state.conversationKind === "review_thread"
                ? state.reviewCommentId
                : state.triggeringCommentId;
            if (commentId === null) {
                return;
            }
            await createGitHubReaction({
                api: config.api,
                commentId,
                content,
                credentials: config.credentials,
                installationId,
                owner: state.owner,
                repo: state.repo,
                subject: state.conversationKind === "review_thread"
                    ? "pull_request_review_comment"
                    : "issue_comment",
            });
        },
    };
    return { github, thread };
}
function requiredNumber(value, name) {
    if (typeof value === "number" && Number.isFinite(value)) {
        return value;
    }
    throw new Error(`githubChannel: missing ${name}.`);
}
